import type { MeetSemilattice } from '../lattice/lattice.ts';
export declare function foldIn<T>(L: MeetSemilattice<T>, demands: readonly T[]): T;
export declare function witnessesIn<T>(L: MeetSemilattice<T>, demands: readonly T[]): readonly [T, T] | null;

export function foldIn(L, demands) {
    let acc = L.top;
    for (const d of demands)
        acc = L.meet(acc, d);
    return acc;
}
export function witnessesIn(L, demands) {
    const whole = foldIn(L, demands);
    if (L.inhabited(whole))
        return null;
    for (let i = 0; i < demands.length; i++) {
        for (let j = i + 1; j < demands.length; j++) {
            if (!L.inhabited(L.meet(demands[i], demands[j]))) {
                return [demands[i], demands[j]];
            }
        }
    }
    return null;
}

import type { Edge } from '../lattice/types.ts';
export interface Graph {
    readonly size: number;
    id(name: string): number;
    name(id: number): string;
    readonly heads: Int32Array;
    readonly tails: Int32Array;
}
export declare function buildGraph(edges: readonly Edge[]): Graph;
export declare function reachIds(g: Graph, from: number, scratch?: Uint8Array): Uint8Array;

export function buildGraph(edges) {
    const index = new Map();
    const names = [];
    const intern = (s) => {
        const hit = index.get(s);
        if (hit !== undefined)
            return hit;
        const i = names.length;
        names.push(s);
        index.set(s, i);
        return i;
    };
    const pairs = [];
    for (const [a, b] of edges)
        pairs.push([intern(a), intern(b)]);
    const size = names.length;
    const counts = new Int32Array(size);
    for (const [a] of pairs)
        counts[a]++;
    const heads = new Int32Array(size + 1);
    for (let i = 0; i < size; i++)
        heads[i + 1] = heads[i] + counts[i];
    const tails = new Int32Array(pairs.length);
    const cursor = heads.slice();
    for (const [a, b] of pairs)
        tails[cursor[a]++] = b;
    return {
        size,
        id: (name) => index.get(name) ?? -1,
        name: (id) => names[id] ?? '',
        heads,
        tails,
    };
}
export function reachIds(g, from, scratch) {
    const seen = scratch ?? new Uint8Array(g.size);
    if (scratch)
        seen.fill(0);
    if (from < 0 || from >= g.size)
        return seen;
    const queue = [from];
    seen[from] = 1;
    while (queue.length > 0) {
        const v = queue.pop();
        for (let i = g.heads[v]; i < g.heads[v + 1]; i++) {
            const n = g.tails[i];
            if (!seen[n]) {
                seen[n] = 1;
                queue.push(n);
            }
        }
    }
    return seen;
}

import type { Lattice } from '../lattice/lattice.ts';
import type { Scale, Unit } from '../lattice/types.ts';
export interface IdealDebit {
    readonly demand: readonly string[];
    readonly permit: readonly string[];
}
export declare function upset(c: Scale, names: readonly string[]): readonly string[];
export declare function downset(c: Scale, names: readonly string[]): readonly string[];
export declare function isUpset(c: Scale, names: readonly string[]): boolean;
export declare function isDownset(c: Scale, names: readonly string[]): boolean;
export declare function isIdealPair(c: Scale, d: IdealDebit): boolean;
export declare function idealDebit(c: Scale, demand: readonly string[], permit: readonly string[]): IdealDebit;
export declare function idealMeet(a: IdealDebit, b: IdealDebit): IdealDebit;
export declare function idealJoin(a: IdealDebit, b: IdealDebit): IdealDebit;
export declare function idealEntails(a: IdealDebit, b: IdealDebit): boolean;
export declare function idealComplexity(c: Scale, d: IdealDebit): number;
export declare function unitToIdeal(c: Scale, u: Unit): IdealDebit;
export declare function freedom(c: Scale, u: Unit): number;
export declare function unitComplexity(c: Scale, u: Unit): number;
export declare function fromIdeals(c: Scale): Lattice<IdealDebit>;

import { UnitError } from "../lattice/errors.js";
const namesOf = (c) => c.levels;
const sorted = (names) => [...new Set(names)].sort();
const has = (xs, name) => xs.includes(name);
export function upset(c, names) {
    return sorted(namesOf(c).filter((_, i) => names.some((n) => c.leq(c.rank(n), i))));
}
export function downset(c, names) {
    return sorted(namesOf(c).filter((_, i) => names.some((n) => c.leq(i, c.rank(n)))));
}
export function isUpset(c, names) {
    const closed = upset(c, names);
    return names.length === closed.length && names.every((n) => has(closed, n));
}
export function isDownset(c, names) {
    const closed = downset(c, names);
    return names.length === closed.length && names.every((n) => has(closed, n));
}
export function isIdealPair(c, d) {
    return isUpset(c, d.demand) && isDownset(c, d.permit);
}
export function idealDebit(c, demand, permit) {
    const pair = { demand: sorted(demand), permit: sorted(permit) };
    if (!isIdealPair(c, pair)) {
        throw new UnitError('MALFORMED', 'a debit that is not a pair of ideals', {
            demand: pair.demand,
            permit: pair.permit,
        });
    }
    return pair;
}
export function idealMeet(a, b) {
    return {
        demand: sorted(a.demand.filter((n) => has(b.demand, n))),
        permit: sorted([...a.permit, ...b.permit]),
    };
}
export function idealJoin(a, b) {
    return {
        demand: sorted([...a.demand, ...b.demand]),
        permit: sorted(a.permit.filter((n) => has(b.permit, n))),
    };
}
function idealInhabited(d) {
    return d.demand.some((n) => has(d.permit, n));
}
export function idealEntails(a, b) {
    return a.demand.every((n) => has(b.demand, n)) && a.permit.every((n) => has(b.permit, n));
}
export function idealComplexity(c, d) {
    const omega = namesOf(c);
    return omega.filter((n) => !has(d.demand, n)).length
        + omega.filter((n) => !has(d.permit, n)).length;
}
export function unitToIdeal(c, u) {
    return {
        demand: upset(c, [u.floor]),
        permit: downset(c, [u.ceiling]),
    };
}
export function freedom(c, u) {
    const d = unitToIdeal(c, u);
    const between = d.demand.filter((n) => has(d.permit, n)).length;
    return between > 1 ? Math.log2(between) : 0;
}
export function unitComplexity(c, u) {
    return idealComplexity(c, unitToIdeal(c, u));
}
export function fromIdeals(c) {
    const omega = namesOf(c);
    return {
        bottom: { demand: [], permit: [] },
        top: { demand: [...omega], permit: [...omega] },
        leq: (a, b) => idealEntails(a, b),
        meet: (a, b) => idealMeet(a, b),
        join: (a, b) => idealJoin(a, b),
        show: (x) => `{${x.demand.join(',')}}/{${x.permit.join(',')}}`,
        inhabited: (x) => idealInhabited(x),
    };
}

export declare function chunkCount(n: number): number;
export declare class WideMask {
    readonly words: Uint32Array;
    readonly width: number;
    constructor(width: number, words?: Uint32Array);
    static fromTokens(tokens: readonly string[], allowed: ReadonlySet<string>): WideMask;
    set(bit: number): void;
    has(bit: number): boolean;
    and(other: WideMask): WideMask;
    or(other: WideMask): WideMask;
    difference(other: WideMask): WideMask;
    subsetOf(other: WideMask): boolean;
    size(): number;
    members(tokens: readonly string[]): readonly string[];
    static filled(width: number): WideMask;
}

import { UnitError } from "../lattice/errors.js";
import { WIDTH } from "./packed.js";
export function chunkCount(n) {
    if (n <= 0)
        return 0;
    return Math.ceil(n / WIDTH);
}
export class WideMask {
    words;
    width;
    constructor(width, words) {
        this.width = width;
        this.words = words ?? new Uint32Array(chunkCount(width));
    }
    static fromTokens(tokens, allowed) {
        const m = new WideMask(tokens.length);
        tokens.forEach((t, i) => {
            if (allowed.has(t))
                m.set(i);
        });
        return m;
    }
    set(bit) {
        if (bit < 0 || bit >= this.width) {
            throw new UnitError('MALFORMED', `bit ${bit} is outside a mask of width ${this.width}`, {
                bit,
                width: this.width,
            });
        }
        this.words[bit >> 5] |= 1 << (bit & 31);
    }
    has(bit) {
        if (bit < 0 || bit >= this.width)
            return false;
        return (this.words[bit >> 5] & (1 << (bit & 31))) !== 0;
    }
    and(other) {
        const w = Math.max(this.width, other.width);
        const out = new WideMask(w);
        const n = Math.min(this.words.length, other.words.length);
        for (let i = 0; i < n; i++)
            out.words[i] = this.words[i] & other.words[i];
        return out;
    }
    or(other) {
        const w = Math.max(this.width, other.width);
        const out = new WideMask(w);
        for (let i = 0; i < out.words.length; i++) {
            out.words[i] = (this.words[i] ?? 0) | (other.words[i] ?? 0);
        }
        return out;
    }
    difference(other) {
        const w = Math.max(this.width, other.width);
        const out = new WideMask(w);
        for (let i = 0; i < out.words.length; i++) {
            out.words[i] = (this.words[i] ?? 0) & ~(other.words[i] ?? 0);
        }
        const spare = w % 32;
        if (spare !== 0 && out.words.length > 0) {
            out.words[out.words.length - 1] &= (1 << spare) - 1;
        }
        return out;
    }
    subsetOf(other) {
        const n = Math.max(this.words.length, other.words.length);
        for (let i = 0; i < n; i++) {
            const a = this.words[i] ?? 0;
            const b = other.words[i] ?? 0;
            if ((a & ~b) !== 0)
                return false;
        }
        return true;
    }
    size() {
        let n = 0;
        for (let i = 0; i < this.width; i++)
            if (this.has(i))
                n++;
        return n;
    }
    members(tokens) {
        return tokens.filter((_, i) => this.has(i));
    }
    static filled(width) {
        const m = new WideMask(width);
        if (width <= 0)
            return m;
        m.words.fill(0xffffffff);
        const spare = width % 32;
        if (spare !== 0)
            m.words[m.words.length - 1] = (1 << spare) - 1;
        return m;
    }
}

import type { Interval } from '../lattice/forms.ts';
import type { Lattice } from '../lattice/lattice.ts';
import type { World } from '../lattice/obligatory.ts';
export declare function price<T>(bits: (held: T) => number, before: T, after: T): number;
export declare function looksLeft(L: Lattice<Interval>, world: World<Interval>, origin: string): number;
export declare function pay(L: Lattice<Interval>, world: World<Interval>, origin: string): World<Interval>;

import { sign } from "../field/sign.js";
import { UnitError } from "../lattice/errors.js";
import { cell, parts } from "../lattice/obligatory.js";
export function price(bits, before, after) {
    return bits(before) - bits(after);
}
export function looksLeft(L, world, origin) {
    return parts(L, world.get(origin) ?? cell(origin), world).ceiling.hi;
}
export function pay(L, world, origin) {
    const held = parts(L, world.get(origin) ?? cell(origin), world);
    if (held.ceiling.hi - 1 < held.floor.lo)
        throw new UnitError('attention-spent', `obligations: REFUSE·attention ${origin} has no look left: an act nobody pays for is not taken`);
    return sign(L, world, origin, { lo: L.top.lo, hi: held.ceiling.hi - 1 });
}

import type { Scale, State, Unit } from '../lattice/types.ts';
export declare const WIDTH = 32;
export interface Packed {
    readonly demanded: number;
    readonly permitted: number;
    readonly limiting: number;
    readonly required: number;
    readonly demand: number;
    readonly limit: number;
}
export declare const opinion: (demanded: number, permitted: number, limiting: number, required: number) => Packed;
export interface Packer {
    readonly width: number;
    readonly joinWidth: number;
    readonly limitWidth: number;
    free(): Packed;
    pack(u: Unit): Packed;
    unpack(subject: string, p: Packed): Unit;
    state(p: Packed): State;
    clashing(p: Packed): string[];
    clashingLimits(p: Packed): string[];
    maskOf(level: string): number;
    accepts(p: Packed, mask: number): boolean;
    above(jBit: number): number;
    coherent(p: Packed): boolean;
}
export declare const or: (a: Packed, b: Packed) => Packed;
export declare const and: (a: Packed, b: Packed) => Packed;
export declare function packer(c: Scale): Packer;
export declare function canonical(pk: Packer, p: Packed): Packed;

import { UnitError } from "../lattice/errors.js";
export const WIDTH = 32;
export const opinion = (demanded, permitted, limiting, required) => ({
    demanded,
    permitted,
    limiting,
    required,
    demand: demanded,
    limit: permitted,
});
const clashes = (p) => p.demanded & ~p.permitted;
const dualClashes = (p) => p.limiting & ~p.required;
const isConflict = (p) => clashes(p) !== 0;
export const or = (a, b) => opinion(a.demanded & b.demanded, a.permitted | b.permitted, a.limiting & b.limiting, a.required | b.required);
export const and = (a, b) => opinion(a.demanded | b.demanded, a.permitted & b.permitted, a.limiting | b.limiting, a.required & b.required);
const ones = (n) => (n === WIDTH ? -1 : (1 << n) - 1);
export function packer(c) {
    const joins = c.joins();
    const limits = c.limits();
    if (joins.length > WIDTH || limits.length > WIDTH) {
        throw new UnitError('MALFORMED', `this scale has ${joins.length} demand-debits and ${limits.length} ` +
            `limit-debits; each opinion holds at most ${WIDTH}`, { joins: joins.length, limits: limits.length, width: WIDTH });
    }
    const allJ = ones(joins.length);
    const allM = ones(limits.length);
    const above = joins.map((j) => {
        let m = 0;
        limits.forEach((lim, bit) => {
            if (c.leq(j, lim))
                m |= 1 << bit;
        });
        return m;
    });
    const miAboveAll = (jiMask) => {
        let acc = allM;
        for (let bit = 0; bit < joins.length; bit++) {
            if ((jiMask & (1 << bit)) !== 0)
                acc &= above[bit];
        }
        return acc;
    };
    const jiBelowAll = (miMask) => {
        let out = 0;
        for (let bit = 0; bit < joins.length; bit++) {
            if ((miMask & ~above[bit]) === 0)
                out |= 1 << bit;
        }
        return out;
    };
    const joinOf = (mask) => joins.reduce((acc, j, bit) => ((mask & (1 << bit)) !== 0 ? c.higher(acc, j) : acc), c.bottomIx);
    return {
        width: joins.length,
        joinWidth: joins.length,
        limitWidth: limits.length,
        free: () => opinion(0, allJ, 0, allM),
        pack(u) {
            const f = c.rank(u.floor);
            const cl = c.rank(u.ceiling);
            let demanded = 0;
            let permitted = 0;
            joins.forEach((j, bit) => {
                if (c.leq(j, f))
                    demanded |= 1 << bit;
                if (c.leq(j, cl))
                    permitted |= 1 << bit;
            });
            let limiting = 0;
            let required = 0;
            limits.forEach((m, bit) => {
                if (c.leq(cl, m))
                    limiting |= 1 << bit;
                if (c.leq(f, m))
                    required |= 1 << bit;
            });
            return opinion(demanded, permitted, limiting, required);
        },
        unpack: (subject, p) => ({
            subject,
            floor: c.levels[joinOf(p.demanded)],
            ceiling: c.levels[joinOf(p.permitted)],
        }),
        state(p) {
            if (isConflict(p))
                return 'CONFLICT';
            if (p.demanded !== 0)
                return 'REQUIRED';
            if (p.permitted !== allJ)
                return 'FORBIDDEN';
            return 'FREE';
        },
        clashing: (p) => joins.filter((_, bit) => (clashes(p) & (1 << bit)) !== 0).map((j) => c.levels[j]),
        clashingLimits: (p) => limits.filter((_, bit) => (dualClashes(p) & (1 << bit)) !== 0).map((m) => c.levels[m]),
        maskOf(level) {
            const l = c.rank(level);
            let m = 0;
            joins.forEach((j, bit) => {
                if (c.leq(j, l))
                    m |= 1 << bit;
            });
            return m;
        },
        accepts: (p, mask) => (p.demanded & ~mask) === 0 && (mask & ~p.permitted) === 0,
        above: (jBit) => above[jBit] ?? 0,
        coherent(p) {
            return (p.required === miAboveAll(p.demanded) &&
                p.limiting === miAboveAll(p.permitted) &&
                p.demanded === jiBelowAll(p.required) &&
                p.permitted === jiBelowAll(p.limiting));
        },
    };
}
export function canonical(pk, p) {
    return pk.pack(pk.unpack('', p));
}

import type { Method } from '../lattice/types.ts';
export declare const METHODS: readonly ["declared", "statistics", "sample", "exact"];
export declare function weakest(methods: Iterable<Method>): Method;

import { chain } from "../lattice/order.js";
import { compose, unit } from "./unit.js";
export const METHODS = ['declared', 'statistics', 'sample', 'exact'];
export function weakest(methods) {
    const c = chain(METHODS);
    const units = [...methods].map((m) => unit('evidence', { floor: METHODS[0], ceiling: m }));
    return units.length === 0 ? 'exact' : compose(c, units).ceiling;
}

import type { Scale, Unit } from '../lattice/types.ts';
export interface Register {
    readonly demanded: readonly string[];
    readonly limiting: readonly string[];
}
export declare function register(c: Scale, u: Unit): Register;
export declare function rebuild(c: Scale, reg: Register, subject?: string): Unit;

export function register(c, u) {
    const f = c.rank(u.floor);
    const cl = c.rank(u.ceiling);
    return {
        demanded: c.joins().filter((j) => c.leq(j, f)).map((j) => c.levels[j]),
        limiting: c.limits().filter((m) => c.leq(cl, m)).map((m) => c.levels[m]),
    };
}
export function rebuild(c, reg, subject = '') {
    let floor = c.bottomIx;
    for (const name of reg.demanded)
        floor = c.higher(floor, c.rank(name));
    let ceiling = c.topIx;
    for (const name of reg.limiting)
        ceiling = c.lower(ceiling, c.rank(name));
    return { subject, floor: c.levels[floor], ceiling: c.levels[ceiling] };
}

export declare function unitStream(seed: number): () => number;
export declare function permute<T>(xs: readonly T[], salt: number): T[];
export declare function permutationBlind<T, R>(values: readonly T[], claim: (xs: readonly T[]) => R, draws?: number): boolean;

function stream(seed) {
    let s = (Math.imul(seed + 1, 2654435761) ^ 0x5f3759df) >>> 0;
    return () => {
        s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
        return s;
    };
}
export function unitStream(seed) {
    const next = stream(seed);
    return () => next() / 4294967296;
}
export function permute(xs, salt) {
    const next = stream(salt);
    const out = xs.slice();
    for (let i = out.length - 1; i > 0; i--) {
        const j = next() % (i + 1);
        const t = out[i];
        out[i] = out[j];
        out[j] = t;
    }
    return out;
}
export function permutationBlind(values, claim, draws = 8) {
    const want = JSON.stringify(claim(values));
    for (let d = 0; d < draws; d++) {
        if (JSON.stringify(claim(permute(values, d + 1))) !== want)
            return false;
    }
    return true;
}

import type { Scale, Unit } from '../lattice/types.ts';
export declare function touches(c: Scale, mine: Unit, folded: Unit): boolean;
export declare function holds(c: Scale, units: readonly Unit[], index: number): boolean;

import { fuse } from "./unit.js";
export function touches(c, mine, folded) {
    return c.rank(mine.floor) === c.rank(folded.floor) || c.rank(mine.ceiling) === c.rank(folded.ceiling);
}
export function holds(c, units, index) {
    if (index < 0 || index >= units.length)
        return false;
    const whole = fuse(c, units);
    const rest = units.filter((_, i) => i !== index);
    const next = fuse(c, rest);
    return next.floor !== whole.floor || next.ceiling !== whole.ceiling;
}

import type { Scale, State, Unit } from '../lattice/types.ts';
export declare function statesPerDebit(c: Scale, u: Unit): [string, State][];
export declare function anyOf(c: Scale, units: readonly Unit[]): Unit[];
export declare function missing(c: Scale, have: Unit, want: Unit): {
    raiseFloorTo: string[];
    raiseCeilingTo: string[];
};
export declare function complexity(c: Scale, u: Unit): number;

import { unitComplexity } from "./ideal.js";
export function statesPerDebit(c, u) {
    const f = c.rank(u.floor);
    const cl = c.rank(u.ceiling);
    return c.joins().map((j) => {
        const demanded = c.leq(j, f);
        const permitted = c.leq(j, cl);
        return [
            c.levels[j],
            demanded ? (permitted ? 'REQUIRED' : 'CONFLICT') : permitted ? 'FREE' : 'FORBIDDEN',
        ];
    });
}
export function anyOf(c, units) {
    const rank = (u) => [c.rank(u.floor), c.rank(u.ceiling)];
    const holds = (f, cl, l) => c.leq(f, l) && c.leq(l, cl);
    const levels = [...c.levels.keys()];
    let live = units.filter((u) => {
        const [f, cl] = rank(u);
        return c.leq(f, cl);
    });
    for (let changed = true; changed;) {
        changed = false;
        outer: for (let i = 0; i < live.length; i++) {
            for (let j = i + 1; j < live.length; j++) {
                const [af, ac] = rank(live[i]);
                const [bf, bc] = rank(live[j]);
                const lo = c.lower(af, bf);
                const hi = c.higher(ac, bc);
                const gains = levels.some((l) => holds(lo, hi, l) && !holds(af, ac, l) && !holds(bf, bc, l));
                if (gains)
                    continue;
                live = [
                    ...live.filter((_, k) => k !== i && k !== j),
                    { subject: live[i].subject, floor: c.levels[lo], ceiling: c.levels[hi] },
                ];
                changed = true;
                break outer;
            }
        }
    }
    return live.sort((x, y) => {
        const [xf, xc] = rank(x);
        const [yf, yc] = rank(y);
        return xf - yf || xc - yc;
    });
}
export function missing(c, have, want) {
    const [hf, hc] = [c.rank(have.floor), c.rank(have.ceiling)];
    const [wf, wc] = [c.rank(want.floor), c.rank(want.ceiling)];
    const all = [...c.levels.keys()];
    const weakestOf = (works) => {
        const ok = all.filter(works);
        return ok.filter((l) => !ok.some((o) => o !== l && c.leq(o, l))).map((l) => c.levels[l]);
    };
    return {
        raiseFloorTo: c.leq(wf, hf) ? [] : weakestOf((l) => c.leq(wf, c.higher(hf, l))),
        raiseCeilingTo: c.leq(wc, hc) ? [] : weakestOf((l) => c.leq(wc, c.higher(hc, l))),
    };
}
export function complexity(c, u) {
    return unitComplexity(c, u);
}

import type { BoolView, DebitOutcome, Scale, State, Unit } from '../lattice/types.ts';
export declare function unit(subject: string, bounds: {
    floor: string;
    ceiling: string;
}): Unit;
export declare const permitAll: (c: Scale, subject: string) => Unit;
export declare function state(c: Scale, u: Unit): State;
export declare function asBoolean(c: Scale, u: Unit): BoolView;
export declare function bitLoss(c: Scale): {
